/// Extern-only kernels are unaffected by extern-window placement: the window
/// starts at offset 0 and a sized buffer round-trips at `buf[0]`.

fn a_barrier_exchange_records_one_full_cta_generation() {
    let r = run(
        &ptx!(parse "success/shared_exchange_with_barrier"),
        in_out_config(2, 2),
    );
    let g = &r.graph;
    let barriers: Vec<_> = g
        .generations()
        .values()
        .filter(|generation| matches!(generation.kind, GenerationKind::Barrier { .. }))
        .collect();
    assert_eq!(barriers.len(), 1);
    assert_eq!(barriers[0].contributions.len(), 2);
    assert!(
        barriers[0]
            .contributions
            .iter()
            .all(|c| c.kind == ContributionKind::Blocking)
    );
    assert_eq!(barriers[0].releases.len(), 2);
    for t in 0..2 {
        assert!(matches!(
            kinds(g, t).as_slice(),
            [
                EventKind::Access(_),
                EventKind::Access(_),
                EventKind::Contribute(_),
                EventKind::Resume(_),
                EventKind::Access(_),
                EventKind::Access(_),
                EventKind::Exit
            ]
        ));
    }
    assert_eq!(g.terminal(), &Terminal::Completed);
}

